// ======================================================================
// Policy struct
// ======================================================================

type StaticComposedSendPolicy struct {
	// NL→IR Item C1 Path A: the current event's typed `_event.data` payload,
	// lifted from the dequeued event by PopulateEventMetadata and read by the
	// native transition guards (`p.pending<Event>Payload.<field>`). Mirrors
	// the Rust policy's `pending_payload` / the C11 `sm->pending_payload`.
	pendingPayloadTag StaticComposedSendPayloadTag
	pendingBatchSentPayload StaticComposedSendBatchSentPayload
	pendingCountedSentPayload StaticComposedSendCountedSentPayload

	pendingEventData string
	// W3C SCXML 5.10: Session ID
	SessionID string
	// ── SCE Accepted Subset §2.15: the datamodel="sce-static" variables ──
	// W3C SCXML 5.2: the `deliveries` datamodel variable, published (`sce:direction="out"`).
	vDeliveries uint32
	// W3C SCXML 5.2: the `item_count` datamodel variable, published (`sce:direction="out"`).
	vItemCount uint32
	// W3C SCXML 5.2: the `tag_count` datamodel variable, published (`sce:direction="out"`).
	vTagCount uint32
	// W3C SCXML 5.2: the `id_sum` datamodel variable, published (`sce:direction="out"`).
	vIdSum uint32
	// W3C SCXML 5.2: the `cell_sum` datamodel variable, published (`sce:direction="out"`).
	vCellSum uint32
	// W3C SCXML 5.2: the `level_count` datamodel variable, published (`sce:direction="out"`).
	vLevelCount uint32
	// W3C SCXML 5.2: the `first_maybe` datamodel variable, published (`sce:direction="out"`).
	vFirstMaybe optional.Of[uint16]
	// W3C SCXML 5.2: the `late_sum` datamodel variable, published (`sce:direction="out"`).
	vLateSum uint32
	// W3C SCXML 5.2: the `late` datamodel variable, published (`sce:direction="out"`).
	vLate []uint8
	// W3C SCXML 5.2: the `refusals` datamodel variable, published (`sce:direction="out"`).
	vRefusals uint32
	// W3C SCXML 5.2: the `held` datamodel variable.
	vHeld []uint8
	// W3C SCXML 5.2: the `counted_deliveries` datamodel variable, published (`sce:direction="out"`).
	vCountedDeliveries uint32
	// W3C SCXML 5.2: the `counted_sum` datamodel variable, published (`sce:direction="out"`).
	vCountedSum uint32
	// W3C SCXML 5.2: the `counted_hops` datamodel variable, published (`sce:direction="out"`).
	vCountedHops uint8
	// W3C SCXML 6.4: Parent communication (unbounded — see sce.ParentEventQueue)
	ParentExternalQueue *sce.ParentEventQueue
	InvokeID           string
	ChildSessionID     string
	// W3C SCXML C.1: the id of the session that invoked this one, whose
	// published location reaches it as `#_parent` does (docs/adr/0090); empty
	// for a session its host started.
	ParentSessionID    string
	// §scxml-6.4.3: invoke param VALUES staged by the parent, applied after
	// this machine's datamodel init so they override its `<data>` defaults.
	pendingParams      map[string]interface{}
}

// NewStaticComposedSendPolicy creates a new policy with default values.
func NewStaticComposedSendPolicy() StaticComposedSendPolicy {
	return StaticComposedSendPolicy{
		// docs/adr/0045: a session has an id, which a saved state names it by and
		// a peer addresses it by. A host that has one for it gives it with
		// SetSessionID before it starts the machine; a child's is its parent's
		// and the id it was started under.
		SessionID: sce.DrawSessionID(),
		vDeliveries: 0,
		vItemCount: 0,
		vTagCount: 0,
		vIdSum: 0,
		vCellSum: 0,
		vLevelCount: 0,
		vFirstMaybe: optional.None[uint16](),
		vLateSum: 0,
		vLate: nil,
		vRefusals: 0,
		vHeld: nil,
		vCountedDeliveries: 0,
		vCountedSum: 0,
		vCountedHops: 0,
	}
}

// SetSessionID gives this session the id its host has for it, in place of the
// one it drew: an XML Nmtoken, since another session addresses this one as
// `#_scxml_<id>` and every child's id is this one's and the id the child was
// started under (docs/adr/0045). Refused for anything else. Called before the
// machine starts, since what it sends names it by the id it began with.
// Declared whether or not a saved state can hold the machine: a root's id is
// bound when the machine is created, whether or not it saves.
func (p *StaticComposedSendPolicy) SetSessionID(id string) error {
	if reason := sce.SessionIDRefusalOf(id); reason != "" {
		return sce.Refuse(reason)
	}
	p.SessionID = id
	return nil
}

